<?php

use OznerOmali\LaravelToI18nextLangParser\Support\TypeScriptGenerator;

it('renders namespaces as literal-typed resources', function (): void {
    $ts = (new TypeScriptGenerator)->generate([
        'orders' => ['ready' => 'Order #{{orderId}} is "ready"', 'tiers' => ['x_one' => 'a', 'x_other' => 'b']],
        'auth' => ['login.title' => 'Sign in', 'empty' => [], 'list' => ['a', 1, 1.5, true, false, null]],
    ], 'en');

    expect($ts)->toBe(<<<'TS'
        // Generated by `php artisan lang:to-i18next` from the [en] translations. Do not edit.
        // See https://www.i18next.com/overview/typescript for wiring it into CustomTypeOptions.

        export interface Resources {
          "auth": {
            "login.title": "Sign in";
            "empty": readonly [];
            "list": readonly ["a", 1, 1.5, true, false, null];
          };
          "orders": {
            "ready": "Order #{{orderId}} is \"ready\"";
            "tiers": {
              "x_one": "a";
              "x_other": "b";
            };
          };
        };

        export default Resources;

        TS);
});

it('renders an empty resource set', function (): void {
    expect((new TypeScriptGenerator)->generate([], 'en'))->toContain('export interface Resources {};');
});
